     [('权重不变但阈值提高','召回和误检仍可能变化','发布清单中的阈值差异'),('类别顺序换了','同一输出索引会被错误解释','names 与训练类别映射'),('只回退 weights','可能与新预处理或配置不兼容','完整发布组合的一致性')],
